 @Test void refundAuditFailureKeepsLeaseAndRecoveryReusesCollectedChannelRefund(){var f=fixture();paid(f);String refund=internalRefund(f,101);org.springframework.test.util.ReflectionTestUtils.setField(finance,"leaseMs",500L);db.execute("CREATE FUNCTION reject_b2_refund_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='service.trade.refund.result' THEN RAISE EXCEPTION 'TEST_ONLY audit outage';END IF;RETURN NEW;END $$");db.execute("CREATE TRIGGER b2_refund_audit_fault BEFORE INSERT ON audit_event FOR EACH ROW EXECUTE FUNCTION reject_b2_refund_audit()");try{assertThrows(org.springframework.dao.DataAccessException.class,()->finance.driveRefund(UUID.fromString(refund)));assertEquals(0,readTrade(f).data().get("refunded_fen").asInt());}finally{db.execute("DROP TRIGGER b2_refund_audit_fault ON audit_event");db.execute("DROP FUNCTION reject_b2_refund_audit()");org.springframework.test.util.ReflectionTestUtils.setField(finance,"leaseMs",60000L);}org.awaitility.Awaitility.await().atMost(Duration.ofSeconds(10)).until(()->db.queryForObject("SELECT lease_until<clock_timestamp() FROM service_trade_refunds WHERE id=?",Boolean.class,UUID.fromString(refund)));finance.driveRefund(UUID.fromString(refund));assertEquals(101,readTrade(f).data().get("refunded_fen").asInt());assertEquals(1,db.queryForObject("SELECT count(*) FROM simulated_payment_refund_requests WHERE refund_no=(SELECT refund_no FROM service_trade_refunds WHERE id=?)",Integer.class,UUID.fromString(refund)));}
