 @Test void closeAndIncomingCollectionSerializeWithoutRevivalOrLostResponsibility()throws Exception{var f=fixture();var a=attempt(f);String attempt=a.data().get("attempt_id").asString();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var latch=new CountDownLatch(1);var cancel=pool.submit(()->{latch.await();return tradeCancel(f.trade(),0,user,key());});var collection=pool.submit(()->{latch.await();outcome(attempt,"SUCCEEDED",101,"CNY");return query(f,0);});latch.countDown();var c=cancel.get(30,TimeUnit.SECONDS);var q=collection.get(30,TimeUnit.SECONDS);assertTrue(Set.of(200,409).contains(c.status()),c.body().toString());assertTrue(Set.of(200,409).contains(q.status()),q.body().toString());}finance.queryTrade(UUID.fromString(f.trade()));var row=readTrade(f).data();if("CANCELLED".equals(row.get("order_state").asString())){assertEquals("RELEASED",row.get("capacity_state").asString());assertEquals(0,row.get("paid_fen").asInt());assertEquals(1,db.queryForObject("SELECT count(*) FROM payment_cases c JOIN payments p ON p.id=c.payment_id WHERE p.service_trade_id=? AND c.reason_code='LATE_COLLECTION'",Integer.class,UUID.fromString(f.trade())));}else{assertEquals("CONFIRMED",row.get("order_state").asString());assertEquals("CONFIRMED",row.get("capacity_state").asString());assertEquals(101,row.get("paid_fen").asInt());}assertEquals(1,db.queryForObject("SELECT count(*) FROM payment_receipts WHERE attempt_id=?",Integer.class,UUID.fromString(attempt)));}
